mapper.select:
select ti.id track_id, ti.track_title, ti.album_id, ti.cover_url, ti.media_duration, ti.status, max(if(ts.stat_type = '0701', ts.stat_num, 0)) as playStatNum, max(if(ts.stat_type = '0702', ts.stat_num, 0)) as collectStatNum, max(if(ts.stat_type = '0703', ts.stat_num, 0)) as praiseStatNum, max(if(ts.stat_type = '0704', ts.stat_num, 0)) as commentStatNum from track_info ti inner join track_stat ts on ti.id = ts.track_id
and ti.user_id = #{vo.userId}
and ti.status = #{vo.status}
and ti.track_title like concat('%',#{vo.track_title},'%')
group by ti.id order by ti.id desc
